{"language":"js","summary":"Searching the working directory for definitions of add","code":"const cwd = process.cwd();
const pats = [
  String.raw`\bfn\s+add\b`,
  String.raw`\bfunction\s+add\b`,
  String.raw`\bdef\s+add\b`,
  String.raw`\bfunc\s+(\([^)]*\)\s*)?add\b`,
  String.raw`\b(const|let|var)\s+add\s*=`,
];
const res = await parallel(pats.map(p => async () => {
  try { return [p, (await tool.grep({ pattern: p, path: cwd })).text]; } catch (e) { return [p, 'ERR ' + e]; }
}));
print(cwd);
for (const [p, t] of res) print('--- ' + p + '\n' + t.slice(0, 1500));"}
